//! A model's hyperparameters.
//!
//! # Provenance
//!
//! Ported from, in the reference checkout:
//!
//! - `llama.cpp/src/llama-hparams.h` -- `llama_hparams`, its two nested
//!   structs, `llama_swa_type` and `is_masked_swa`
//! - `llama.cpp/src/llama-hparams.cpp` -- every member function
//!
//! Both at v0.3.0 (`c1d0e7a00`).
//!
//! # The layout is upstream's
//!
//! `Hparams` keeps every data member of `llama_hparams`, in order, as an
//! `extern struct`, and its fields are generated by `scripts/gen-hparams`
//! between the markers below. The C++ type is trivially copyable, so a
//! layout-identical struct can read the reference model's `hparams` in
//! place: that is how `make loader-diff` compares the port's
//! hyperparameters with the C++ object's field by field, after checking
//! every offset and size against `offsetof` and `sizeof`. Names stay the
//! C++'s, `_impl` suffixes included, so the many sites that read them can
//! be ported line for line.
//!
//! # Arithmetic wraps
//!
//! Every quantity here is `uint32_t`, and the C++ lets products and
//! differences wrap; so do these, with `*%`, `+%` and `-%`.

const std = @import("std");
const impl = @import("impl.zig");

const c = impl.c;

/// Mirrors `LLAMA_MAX_LAYERS` (llama-hparams.h:10 @c1d0e7a00).
pub const max_layers = 512;
/// Mirrors `LLAMA_MAX_EXPERTS` (llama-hparams.h:11 @c1d0e7a00).
pub const max_experts = 1024;

/// Mirrors `llama_expert_gating_func_type` (llama-hparams.h:13 @c1d0e7a00).
pub const ExpertGatingFunc = enum(u32) {
    none = 0,
    softmax = 1,
    sigmoid = 2,
    softmax_weight = 3,
    sqrt_softplus = 4,
    _,
};

/// Mirrors `llama_swa_type` (llama-hparams.h:21 @c1d0e7a00).
pub const SwaType = enum(c_int) {
    none = 0,
    standard = 1,
    chunked = 2,
    symmetric = 3,
    _,
};

/// Mirrors `llama_hparams_posnet` (llama-hparams.h:31 @c1d0e7a00).
pub const Posnet = extern struct {
    n_embd: u32 = 0,
    n_layer: u32 = 0,
};

/// Mirrors `llama_hparams_convnext` (llama-hparams.h:36 @c1d0e7a00).
pub const Convnext = extern struct {
    n_embd: u32 = 0,
    n_layer: u32 = 0,
};

