// Unit Tests

test {
    std.testing.refAllDecls(@This());
}

test "the defaults are the member initializers" {
    const h: Hparams = .{};
    try std.testing.expectEqual(@as(f32, 50.0), h.f_attn_logit_softcapping);
    try std.testing.expectEqual(@as(i32, -1), h.router_layer);
    try std.testing.expectEqual(@as(i32, -1), h.dec_start_token_id);
    try std.testing.expect(std.math.isNegativeInf(h.kda_gate_lower_bound));
    try std.testing.expectEqual(@as(u32, 1), h.n_cls_out);
    try std.testing.expect(h.causal_attn);
}

test "a recurrent pattern marks all but every n-th layer" {
    var h: Hparams = .{ .n_layer_all = 9, .n_layer_nextn = 1 };
    h.setRecrPattern(4, false);
    const want = [_]u32{ 1, 1, 1, 0, 1, 1, 1, 0, 0 };
    try std.testing.expectEqualSlices(u32, &want, h.is_recr_impl[0..9]);
}
